import os,sys,json,base64,zlib,subprocess
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir()
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
    dest=code/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
proofs=list(Path('/kaggle/input').rglob('config.json'))
assert len(proofs)==1,'one exact portable regression proof required'
proof=json.loads(proofs[0].read_text())
assert proof['returncode']==0 and proof['git_commit']=='33e1f62'+'6f08c9ca7daa416e329205a54733a5ca3','v19 proof required, not an older pass'
subprocess.run([sys.executable,str(code/'scripts/build_openbmi_execution_release.py'),
 '--protocol',str(code/'configs/openbmi_independent_protocol_frozen_20261022.json'),
 '--coverage-1-51',str(code/'results/coverage_failed_v8/openbmi_coverage_audit.json'),
 '--coverage-52-54',str(code/'results/identity_52_54_v10/openbmi_coverage_audit.json'),
 '--integration-proof',str(code/'results/subject_integration_v1/out/subject_integration_complete.json'),
 '--portable-proof',str(proofs[0]),'--out-dir','/kaggle/working/out/release',
 '--git-commit','8f931aeadb03739207720c61ffc1ff5d3db2114e'],check=True)
